// Created: 2026-09-14

// /agent/identity: the auth.md agentic-registration identity endpoint, and the
// one genuinely protected resource on this origin.
//
//   POST {"type":"anonymous"}            register; returns a service-signed
//                                        identity assertion (30-day JWT).
//   POST {"type":"identity_assertion"}   re-register with an assertion THIS
//                                        origin issued; returns a fresh one
//                                        for the same registration id.
//   POST {"type":"service_auth"}         400 service_auth_not_enabled: there
//                                        is no email claim ceremony here.
//   GET  Authorization: Bearer <jwt>     read the registration back.
//   GET  (no bearer)                     401 with the RFC 9728 discovery
//                                        hint. This is the honest 401: the
//                                        endpoint has nothing to return
//                                        without an identity.
//
// Identity is optional everywhere else. The scopes an assertion carries are
// the ones an anonymous caller already has; see docs/adr/optional-agent-identity.md.
// Advertised from /.well-known/oauth-authorization-server (agent_auth.identity_endpoint).

import { SITE } from "@/lib/constants";
import {
	AS_METADATA_URL,
	bearerFromHeader,
	challengeDescription,
	IDENTITY_ENDPOINT,
	IDENTITY_TOKEN_TYPE,
	mintIdentityAssertion,
	PRM_URL,
	SCOPES,
	verifyIdentityAssertion,
	wwwAuthenticate,
} from "@/lib/agent-identity";
import { problemResponse } from "@/lib/problem";

export const dynamic = "force-dynamic";

const JSON_HEADERS = {
	"Content-Type": "application/json; charset=utf-8",
	"Cache-Control": "no-store",
};

const ALLOW = "GET, POST, OPTIONS";

function unauthorized(reason?: Parameters<typeof wwwAuthenticate>[0]): Response {
	return problemResponse(
		{
			type: `${SITE.domain}/auth.md`,
			title: "Unauthorized",
			status: 401,
			detail: reason
				? `${challengeDescription(reason)} Discovery: ${PRM_URL}`
				: `GET ${IDENTITY_ENDPOINT} reads an identity back, so it needs one: present the assertion from POST ${IDENTITY_ENDPOINT} as a bearer. Discovery: ${PRM_URL}`,
			instance: "/agent/identity",
		},
		{
			"WWW-Authenticate": wwwAuthenticate(reason),
			"Cache-Control": "no-store",
			Allow: ALLOW,
		},
		{ resource_metadata: PRM_URL, authorization_server_metadata: AS_METADATA_URL },
	);
}

// auth.md registration errors use the OAuth error envelope, not Problem
// Details: an agent following the auth.md skill parses `error`.
function registrationError(
	status: number,
	error: string,
	description: string,
): Response {
	return new Response(
		JSON.stringify({ error, error_description: description }, null, 2),
		{ status, headers: { ...JSON_HEADERS, Allow: ALLOW } },
	);
}

function registrationBody(token: string, claims: { sub: string; exp: number; registration_type: string }) {
	return {
		registration_id: claims.sub,
		registration_type: claims.registration_type,
		identity_assertion: token,
		assertion_type: IDENTITY_TOKEN_TYPE,
		assertion_expires: new Date(claims.exp * 1000).toISOString(),
		// Identity is optional: the scopes are the ones every anonymous caller
		// already holds, and there is no claim ceremony that would widen them.
		scopes: [...SCOPES],
		pre_claim_scopes: [...SCOPES],
		claim: null,
		// The assertion is the bearer. There is no token endpoint to exchange it at.
		token_endpoint: null,
		bearer_method: "header",
		identity_url: IDENTITY_ENDPOINT,
	};
}

export async function GET(req: Request): Promise<Response> {
	const bearer = bearerFromHeader(req.headers.get("authorization"));
	if (bearer === null) return unauthorized();
	const verdict = await verifyIdentityAssertion(bearer);
	if (!verdict.ok) return unauthorized(verdict.reason);
	const { claims } = verdict;
	return new Response(
		JSON.stringify(
			{
				registration_id: claims.sub,
				registration_type: claims.registration_type,
				scopes: claims.scope.split(" "),
				issued_at: new Date(claims.iat * 1000).toISOString(),
				assertion_expires: new Date(claims.exp * 1000).toISOString(),
				issuer: claims.iss,
			},
			null,
			2,
		),
		{ headers: { ...JSON_HEADERS, Allow: ALLOW } },
	);
}

export async function POST(req: Request): Promise<Response> {
	let body: { type?: unknown; assertion?: unknown; assertion_type?: unknown };
	try {
		body = (await req.json()) as typeof body;
	} catch {
		return registrationError(400, "invalid_request", "Body must be a JSON object with a `type` field.");
	}
	if (!body || typeof body !== "object") {
		return registrationError(400, "invalid_request", "Body must be a JSON object with a `type` field.");
	}

	switch (body.type) {
		case "anonymous": {
			const { token, claims } = await mintIdentityAssertion();
			return new Response(JSON.stringify(registrationBody(token, claims), null, 2), {
				status: 201,
				headers: { ...JSON_HEADERS, Allow: ALLOW },
			});
		}
		case "identity_assertion": {
			if (body.assertion_type !== IDENTITY_TOKEN_TYPE) {
				return registrationError(
					400,
					"unsupported_assertion_type",
					`Only ${IDENTITY_TOKEN_TYPE} is accepted, and only when issued by ${SITE.domain}.`,
				);
			}
			if (typeof body.assertion !== "string") {
				return registrationError(400, "invalid_request", "`assertion` must be a string.");
			}
			const verdict = await verifyIdentityAssertion(body.assertion);
			if (!verdict.ok) {
				const code =
					verdict.reason === "expired"
						? "expired"
						: verdict.reason === "wrong_issuer"
							? "invalid_issuer"
							: "invalid_signature";
				return registrationError(400, code, challengeDescription(verdict.reason));
			}
			const { token, claims } = await mintIdentityAssertion({ sub: verdict.claims.sub });
			return new Response(JSON.stringify(registrationBody(token, claims), null, 2), {
				headers: { ...JSON_HEADERS, Allow: ALLOW },
			});
		}
		case "service_auth":
			return registrationError(
				400,
				"service_auth_not_enabled",
				"This origin has no email claim ceremony. Register with type \"anonymous\" instead; identity is optional here.",
			);
		default:
			return registrationError(
				400,
				"invalid_request",
				'`type` must be "anonymous" or "identity_assertion".',
			);
	}
}

export function OPTIONS(): Response {
	return new Response(null, {
		status: 204,
		headers: {
			Allow: ALLOW,
			"Access-Control-Allow-Methods": ALLOW,
			"Access-Control-Allow-Headers": "Content-Type, Accept, Authorization",
			"Access-Control-Allow-Origin": "*",
		},
	});
}
